package com.yuegang.zhihui.notification.application;import com.yuegang.zhihui.common.core.*;import javax.sql.DataSource;import org.springframework.jdbc.core.JdbcTemplate;public final class NotificationQueryService{private final JdbcTemplate jdbc;public NotificationQueryService(DataSource d){jdbc=new JdbcTemplate(d);}public long unread(long user){Long n=jdbc.queryForObject("SELECT COUNT(*) FROM notification_message WHERE user_id=? AND read_at IS NULL",Long.class,user);return n==null?0:n;}public int readAll(long user){return jdbc.update("UPDATE notification_message SET read_at=NOW(6) WHERE user_id=? AND read_at IS NULL",user);}}
